"use client";

import { createContext, useContext, useState, type ReactNode } from "react";

type ToastRecord = { id: number; title: string; description?: string };
const ToastContext = createContext<{ toast: (toast: Omit<ToastRecord, "id">) => void } | null>(null);
export function ToastProvider({ children }: { children: ReactNode }) { const [items, setItems] = useState<ToastRecord[]>([]); function toast(item: Omit<ToastRecord, "id">) { const id = Date.now(); setItems((current) => [...current, { ...item, id }]); window.setTimeout(() => setItems((current) => current.filter((entry) => entry.id !== id)), 5000); } return <ToastContext.Provider value={{ toast }}>{children}<div aria-live="polite" aria-relevant="additions" className="co-fixed co-bottom-4 co-end-4 co-z-50 co-grid co-w-[min(24rem,calc(100%-2rem))] co-gap-2">{items.map((item) => <div key={item.id} className="co-rounded-lg co-border co-border-black/15 co-bg-white co-p-4 co-shadow-lg"><strong className="co-block co-text-sm">{item.title}</strong>{item.description && <p className="co-mt-1 co-text-sm co-text-black/55">{item.description}</p>}<button type="button" className="co-mt-2 co-text-xs co-underline" onClick={() => setItems((current) => current.filter((entry) => entry.id !== item.id))}>Dismiss</button></div>)}</div></ToastContext.Provider>; }
export function useToast() { const context = useContext(ToastContext); if (!context) throw new Error("useToast must be used inside ToastProvider."); return context; }
